for (const [scenarioId, scenario] of Object.entries(scenarios)) {
  const folder = path.join(baseDir, scenarioId);
  fs.mkdirSync(folder, { recursive: true });
  const files = {
    'scenario.json': { id: scenario.id, title: scenario.title, initialRequest: scenario.initialRequest, description: scenario.description, version: '1.0.0', status: 'draft' },
    'hidden-requirements.json': scenario.hiddenRequirements,
    'client-persona.json': scenario.clientPersona,
    'evaluation-rubric.json': scenario.evaluationRubric,
  };
  for (const [fileName, content] of Object.entries(files)) {
    fs.writeFileSync(path.join(folder, fileName), JSON.stringify(content, null, 2) + '\n', 'utf8');
  }
}

console.log(`Created ${Object.keys(scenarios).length} scenario folders.`);
